"""Source for the installed-SDK-only application starter generated by ``init``."""

from __future__ import annotations

import json
import re

_CALLABLE = r"[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*:[A-Za-z_]\w*"


def application_files(target: str) -> dict[str, str]:
    if re.fullmatch(_CALLABLE, target, flags=re.ASCII) is None:
        raise ValueError("--callable must be MODULE:FUNCTION, for example my_app:answer")
    cases = [
        {"id": "france", "input": "Capital of France?", "reference": "Paris"},
        {"id": "japan", "input": "Capital of Japan?", "reference": "Tokyo"},
        {"id": "italy", "input": "Capital of Italy?", "reference": "Rome"},
    ]
    return {
        "evaluate.py": _ENTRYPOINT.replace("__DEFAULT_CALLABLE__", repr(target)),
        "application.py": _APPLICATION,
        "cases.jsonl": "".join(json.dumps(case) + "\n" for case in cases),
        "README.md": _README,
        ".gitignore": "results*.json\nreport*.html\nreport*.md\n__pycache__/\n.evalsi*/\n",
    }


_APPLICATION = '''"""Synthetic offline controls. Replace these with your own application."""


def answer(question: str) -> str:
    capitals = {
        "Capital of France?": "Paris",
        "Capital of Japan?": "Tokyo",
        "Capital of Italy?": "Rome",
    }
    return capitals.get(question, "Unknown")


def regressed(question: str) -> str:
    return "Kyoto" if question == "Capital of Japan?" else answer(question)
'''

_ENTRYPOINT = r'''"""Run a synchronous application with the installed Evals.si SDK."""

from __future__ import annotations

import argparse
import contextlib
import importlib
import inspect
import json
import os
import re
import sys
from collections.abc import Callable, Iterator
from pathlib import Path
from typing import Any, cast

from evalsi import Content, Outcome, Record, Score, evaluate, evaluator
from evalsi.evaluator import MetricSpec, Requirements, ScoreType

DEFAULT_CALLABLE = __DEFAULT_CALLABLE__


def positive_int(value: str) -> int:
    number = int(value)
    if number < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return number


@contextlib.contextmanager
def silenced() -> Iterator[None]:
    """Discard what the application prints, so its logs and exception messages (possibly
    secrets) never reach this command's output or artifacts. Subprocesses and native code
    write to file descriptors 1 and 2, not sys.stdout, so those are redirected too."""
    sys.stdout.flush()
    sys.stderr.flush()
    saved = []
    with open(os.devnull, "w") as sink:
        try:
            for fd in (1, 2):
                try:
                    saved.append((fd, os.dup(fd)))
                except OSError:
                    continue  # not open: nothing to protect
                os.dup2(sink.fileno(), fd)
            with contextlib.redirect_stdout(sink), contextlib.redirect_stderr(sink):
                yield
        finally:
            for fd, copy in saved:
                os.dup2(copy, fd)
                os.close(copy)


def load_cases(path: Path) -> list[Record]:
    records = []
    ids = set()
    with path.open(encoding="utf-8") as source:
        for line_number, line in enumerate(source, 1):
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except ValueError:
                raise ValueError(f"cases line {line_number}: invalid JSON") from None
            if not isinstance(row, dict) or any(
                not isinstance(row.get(key), str) or not row[key].strip()
                for key in ("id", "input", "reference")
            ):
                raise ValueError(
                    f"cases line {line_number}: require nonempty string id, input and reference"
                )
            if row["id"] in ids:
                raise ValueError(f"cases line {line_number}: duplicate id")
            ids.add(row["id"])
            records.append(Record(
                id=row["id"],
                input=Content(text=row["input"]),
                reference=Content(text=row["reference"]),
            ))
    if not records:
        raise ValueError("cases file is empty; add at least one id/input/reference case")
    return records


def load_application(target: str) -> Callable[[str], Any]:
    if re.fullmatch(
        r"[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*:[A-Za-z_]\w*", target, flags=re.ASCII
    ) is None:
        raise ValueError("--callable must be MODULE:FUNCTION, for example my_app:answer")
    module_name, function_name = target.split(":")
    try:
        with silenced():
            application = getattr(importlib.import_module(module_name), function_name)
    except (Exception, SystemExit):
        raise ValueError(
            "cannot load callable; check MODULE:FUNCTION, its dependencies and Python import path. "
            "Import the module locally to debug; application error details were suppressed."
        ) from None
    if not callable(application) or inspect.iscoroutinefunction(application):
        raise ValueError("callable must be synchronous: def answer(input: str) -> str")
    return cast(Callable[[str], Any], application)


def reproduction_metadata(target: str, cases: Path, case_id: str) -> dict[str, Any]:
    try:
        relative_cases = cases.resolve().relative_to(Path(__file__).resolve().parent).as_posix()
    except (OSError, ValueError):
        return {}
    values = ((target, 256), (relative_cases, 512), (case_id, 256))
    if any(
        not value.isascii() or not value.isprintable() or len(value) > limit
        for value, limit in values
    ):
        return {}
    if (
        "\\" in relative_cases or ":" in relative_cases
        or relative_cases.startswith("-") or case_id.startswith("-")
    ):
        return {}
    return {
        "evalsi_application_reproduction": {
            "version": 1,
            "callable": target,
            "cases": relative_cases,
            "case": case_id,
        }
    }


def main() -> int:
    parser = argparse.ArgumentParser(
        description=__doc__,
        epilog="Exit 0: all checks passed; 3: wrong answers; 1: execution/configuration error; "
               "2: command-line usage error. Passing a small sample does not establish quality.",
    )
    parser.add_argument("--callable", default=DEFAULT_CALLABLE, dest="target",
                        metavar="MODULE:FUNCTION", help="synchronous callable: (input: str) -> str")
    parser.add_argument("--cases", type=Path, default=Path(__file__).with_name("cases.jsonl"),
                        help="JSONL with unique string id, input and reference fields")
    parser.add_argument("--limit", type=positive_int, help="run only the first N cases")
    parser.add_argument("--case", dest="case_id", metavar="ID", help="rerun exactly one case")
    parser.add_argument("--output", type=Path, default=Path("results.json"),
                        help="SDK result JSON (default: results.json; replaces existing file)")
    args = parser.parse_args()
    try:
        records = load_cases(args.cases)
        if args.case_id is not None:
            records = [record for record in records if record.id == args.case_id]
            if not records:
                raise ValueError("--case did not match any id; inspect the cases file")
        if args.limit is not None:
            records = records[:args.limit]
        application = load_application(args.target)
        for record in records:
            record.metadata.update(reproduction_metadata(args.target, args.cases, record.id))

        @evaluator(
            name="application/exact-match",
            version="1.0.0",
            requires=Requirements(input=True, output=False, reference=True),
            outputs=[MetricSpec("application-exact-match", ScoreType.PASSED)],
        )
        def check(record: Record) -> Score:
            assert record.input is not None
            assert record.reference is not None
            try:
                with silenced():
                    output = application(record.input.as_text())
            except (Exception, SystemExit):
                raise RuntimeError(
                    "application execution failed; rerun this case and debug the callable locally. "
                    "Application exception details were suppressed."
                ) from None
            if not isinstance(output, str) or not output.strip():
                if inspect.iscoroutine(output):
                    output.close()
                raise RuntimeError(
                    "application must return a nonempty string, not None, an object or an awaitable"
                )
            record.output = Content(text=output)
            passed = output == record.reference.as_text()
            return Score(
                passed=passed,
                explanation="Exact match." if passed else "Actual output differs from reference.",
            )

        result = evaluate(records, [check], cache=False, concurrency=1)
        result.save(args.output)
        errors = sum(item.outcome is not Outcome.SCORED for item in result.results)
        failed = sum(score.passed is False for item in result.results for score in item.scores)
        passed = sum(score.passed is True for item in result.results for score in item.scores)
        print(f"Cases: {len(records)} | passed: {passed} | failed: {failed} | "
              f"execution errors: {errors}")
        print(f"Results: {args.output}")
        print("Passing a small sample is not evidence of production quality; "
              "starter cases are synthetic.")
        if errors or passed + failed != len(records):
            print("Execution failed; inspect result reasons and the callable's string contract.",
                  file=sys.stderr)
            return 1
        return 3 if failed else 0
    except (OSError, ValueError) as error:
        # Configuration errors can contain paths/data; only our validated messages are printed.
        if isinstance(error, OSError):
            print("Execution/configuration error: cannot read cases or write results; "
                  "check paths and permissions.", file=sys.stderr)
        else:
            print(f"Execution/configuration error: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
'''

_README = """# Evaluate your application

Only the installed `evalsi` package and Python 3.11+ are needed for these offline
controls. No harness, server, evalsid, Docker, provider key, network or source
checkout is needed. `init` only writes files: it never imports your application.

From this directory, using the Python environment where you installed evalsi:

```bash
python evaluate.py --limit 1 --output results-first.json
python evaluate.py --output results.json
evalsi report results.json -o report.html
python evaluate.py --callable application:regressed --output results-regressed.json
evalsi report results-regressed.json -o report-regressed.html
```

The first two evaluations exit **0**. The deliberately regressed synthetic
application exits **3** because Japan's answer is wrong. Exit **1** means an
application execution, input or output configuration error, not a business
regression. Invalid command-line syntax exits **2**. Execution errors take
precedence over failed checks. The report command only renders evidence; its
exit status does not replace the evaluation's exit status.

## Connect your application

Use `python evaluate.py --callable my_package.my_module:answer`, or select the
default at creation time with
`evalsi init my-evals --template application --callable my_package.my_module:answer`.
The module must be importable in the same Python environment (install your app,
or set its import path). A simple local `application.py` is provided to edit.
Use a thin synchronous adapter for async applications or structured APIs.

The contract is `def answer(input: str) -> str`. The function receives exactly
one case's input string and must return a nonempty string. No response wrapper,
None, coroutine, implicit printed output or JSON object is accepted. Cases are
UTF-8 JSONL with unique nonempty string `id`, `input`, and `reference` fields.
Edit `cases.jsonl` to encode your application's expected behavior; additional
fields are not checks. A custom file can be selected with `--cases path.jsonl`.
The deterministic check is exact, case-sensitive string equality, including
whitespace; it is not a model judge or a general quality score.

Calls run sequentially, once per selected case. Start with `--limit 1`, then run
the full set. To reproduce a failed example:

```bash
python evaluate.py --case japan --output results-japan.json
```

No matched cases, invalid cases, exceptions, missing/empty/wrong-type outputs,
or unexpected skipped checks can pass. Application errors are recorded as SDK
error outcomes, separately from scored failed checks. Standard SDK JSON includes
each case's input, expected reference, actual output when available, and reasons.
`evalsi report` consumes it directly. Existing output files are replaced.

Import errors are actionable configuration errors; application stdout/stderr and
exception details are suppressed to avoid copying secrets into reports. Debug
the callable locally if necessary. This is **not a sandbox** or timeout boundary:
only run trusted code, and implement timeouts in your adapter. Your own
application may perform side effects or need dependencies, network or secrets;
the supplied offline controls do not. Keep credentials in your application's
environment, never in cases, command arguments or committed files.

Three synthetic examples (or one first case) demonstrate plumbing, not release
readiness, statistical confidence or protection against unseen failures.
Replace them with representative, approved cases before making release decisions.
Results and reports contain raw application data: review before sharing. They
are gitignored, not encrypted or automatically redacted.
"""
